   137	  let event: string | undefined;
   138	  let data: string[] = [];
   139	
   140	  const processLine = (line: string): SseMessage | undefined => {
   141	    if (line === '') {
   142	      const message = data.length === 0
   143	        ? undefined
   144	        : { ...(event === undefined ? {} : { event }), data: data.join('\n') };
   145	      event = undefined;
   146	      data = [];
   147	      return message;
   148	    }
   149	    if (line.startsWith(':')) return undefined;
   150	    const colon = line.indexOf(':');
   151	    const field = colon === -1 ? line : line.slice(0, colon);
   152	    const value = colon === -1 ? '' : line.slice(colon + 1).replace(/^ /, '');
   153	    if (field === 'event') event = value;
   154	    if (field === 'data') data.push(value);
   155	    return undefined;
   156	  };
