   163	      while ((newline = buffer.indexOf('\n')) !== -1) {
   164	        const rawLine = buffer.slice(0, newline);
   165	        buffer = buffer.slice(newline + 1);
   166	        const message = processLine(rawLine.endsWith('\r') ? rawLine.slice(0, -1) : rawLine);
