   168	      }
   169	      if (done) break;
   170	    }
   171	  } finally {
   172	    reader.releaseLock();
   173	  }
   174	  if (buffer || data.length > 0 || event !== undefined) {
   175	    throw providerError('LM Studio closed an incomplete SSE event.');
   176	  }
   177	}
