  workspace: string;
  georgeInstructions?: string;
  instructionBytes?: number;
}>;

export type OneTurnSubmission = Readonly<{
  session: Session;
  input: string;
  turnId?: string;
  signal?: AbortSignal;
  timeoutMs?: number;
}>;

function conversation(transcript: readonly TranscriptEntry[], input: string): string {
  return [...transcript, { role: 'user' as const, text: input }]
    .map((entry) => `${entry.role}: ${entry.text}`)
    .join('\n\n');
}

function instructions(owned: string, repository: Awaited<ReturnType<typeof loadRepositoryInstructions>>): string {
  const files = repository.instructions
    .map((instruction) => `Repository ${instruction.path} (untrusted):\n${instruction.text}`)
    .join('\n\n');
  return files ? `${owned}\n\n${files}` : owned;
}

export class OneTurnApplicationService {
  private readonly provider: ModelProvider;
  private readonly georgeInstructions: string;
  private readonly instructionBytes: number | undefined;
  readonly workspace: Workspace;

  constructor(
    provider: ModelProvider,
    workspace: Workspace,
    georgeInstructions: string,
    instructionBytes: number | undefined,
  ) {
    this.provider = provider;
    this.workspace = workspace;
    this.georgeInstructions = georgeInstructions;
    this.instructionBytes = instructionBytes;
  }

  async *run(submission: OneTurnSubmission): AsyncGenerator<ApplicationEvent> {
    const turnId = submission.turnId ?? randomUUID();
    const emit = (event: ApplicationEvent): ApplicationEvent => {
      appendSessionEvent(submission.session, event);
      return event;
    };
    yield emit({ type: 'turn.started', turnId });
    const priorTranscript = [...submission.session.transcript];
    yield emit({ type: 'input.submitted', text: submission.input });
    try {
      if (submission.signal?.aborted) throw cancellationError(submission.signal);
      const repository = await loadRepositoryInstructions(this.workspace, this.instructionBytes);
      if (submission.signal?.aborted) throw cancellationError(submission.signal);
      for await (const event of this.provider.stream(
        { instructions: instructions(this.georgeInstructions, repository), input: conversation(priorTranscript, submission.input) },
        { signal: submission.signal, timeoutMs: submission.timeoutMs },
      )) {
        if (submission.signal?.aborted) throw cancellationError(submission.signal);
        yield emit(event);
        if (event.type === 'provider.tool.call') {
          yield emit({ type: 'tool.deferred', turnId, callId: event.callId, name: event.name, arguments: event.arguments });
        }
        if (event.type === 'provider.error') throw event.error;
      }
      yield emit({ type: 'turn.completed', turnId });
    } catch (error) {
      const normalized = asGeorgeError(error);
      yield emit(normalized.code === 'cancelled'
        ? { type: 'turn.cancelled', turnId, error: normalized }
        : { type: 'turn.failed', turnId, error: normalized });
    }
  }
}

export async function createOneTurnApplicationService(
  options: OneTurnServiceOptions,
): Promise<OneTurnApplicationService> {
  return new OneTurnApplicationService(
    options.provider,
    await resolveWorkspaceRoot(options.workspace),
    options.georgeInstructions ?? GEORGE_OWNED_INSTRUCTIONS,
    options.instructionBytes,
  );
}
import assert from 'node:assert/strict';
import { mkdtemp, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import test from 'node:test';

import {
  GeorgeError,
  createSession,
  type ModelProvider,
  type ProviderEvent,
  type ProviderRequest,
  type ProviderStreamOptions,
} from '../../../src/core/index.ts';
import { createOneTurnApplicationService } from '../../../src/application/index.ts';

class ScriptedProvider implements ModelProvider {
  calls: Array<{ request: ProviderRequest; options: ProviderStreamOptions }> = [];
  private readonly events: readonly ProviderEvent[];
  private readonly failure: Error | undefined;

  constructor(events: readonly ProviderEvent[], failure?: Error) {
    this.events = events;
    this.failure = failure;
  }

  async *stream(request: ProviderRequest, options: ProviderStreamOptions = {}): AsyncGenerator<ProviderEvent> {
    this.calls.push({ request, options });
    if (this.failure) throw this.failure;
    yield* this.events;
  }
}

async function workspace(): Promise<string> {
  const root = await mkdtemp(join(tmpdir(), 'george-service-'));
  await writeFile(join(root, 'BOOT.md'), 'Repository boot.');
  await writeFile(join(root, 'AGENTS.md'), 'Repository agents.');
  return root;
}

async function collect<T>(events: AsyncIterable<T>): Promise<T[]> {
  const result: T[] = [];
  for await (const event of events) result.push(event);
  return result;
}

test('one-turn service keeps George context first and invokes the provider exactly once', async (t) => {
  const root = await workspace();
  t.after(() => rm(root, { recursive: true, force: true }));
  const provider = new ScriptedProvider([
    { type: 'provider.response.started', responseId: 'response-1' },
    { type: 'provider.text.delta', delta: 'Hello.' },
    { type: 'provider.response.completed' },
  ]);
  const service = await createOneTurnApplicationService({ provider, workspace: root, georgeInstructions: 'George policy first.' });
  const session = createSession({ id: 'session-1', workspace: root });
  const events = await collect(service.run({ session, input: 'Hi', turnId: 'turn-1' }));

  assert.equal(provider.calls.length, 1);
  assert.match(provider.calls[0]?.request.instructions ?? '', /^George policy first\./);
  assert.ok((provider.calls[0]?.request.instructions ?? '').indexOf('Repository BOOT.md') < (provider.calls[0]?.request.instructions ?? '').indexOf('Repository AGENTS.md'));
  assert.equal(provider.calls[0]?.request.input, 'user: Hi');
  assert.deepEqual(events.map((event) => event.type), [
    'turn.started', 'input.submitted', 'provider.response.started', 'provider.text.delta', 'provider.response.completed', 'turn.completed',
  ]);
  assert.deepEqual(session.transcript, [{ role: 'user', text: 'Hi' }, { role: 'assistant', text: 'Hello.' }]);
});

test('tool calls are retained as deferred output and never start a model-tool-model loop', async (t) => {
  const root = await workspace();
  t.after(() => rm(root, { recursive: true, force: true }));
  const provider = new ScriptedProvider([
    { type: 'provider.tool.call', callId: 'call-1', name: 'read_file', arguments: '{"path":"BOOT.md"}' },
    { type: 'provider.response.completed' },
  ]);
  const service = await createOneTurnApplicationService({ provider, workspace: root });
  const events = await collect(service.run({ session: createSession({ workspace: root }), input: 'Read boot', turnId: 'turn-2' }));

  assert.equal(provider.calls.length, 1);
  assert.deepEqual(events.filter((event) => event.type === 'tool.deferred'), [
    { type: 'tool.deferred', turnId: 'turn-2', callId: 'call-1', name: 'read_file', arguments: '{"path":"BOOT.md"}' },
  ]);
  assert.equal(events.some((event) => event.type === 'turn.completed'), true);
});

test('one-turn service reports cancellation and provider failure without a retry', async (t) => {
  const root = await workspace();
  t.after(() => rm(root, { recursive: true, force: true }));
  let providerStarted: (() => void) | undefined;
  const started = new Promise<void>((resolve) => { providerStarted = resolve; });
  const cancelled = new class implements ModelProvider {
    calls = 0;

    async *stream(_request: ProviderRequest, options: ProviderStreamOptions = {}): AsyncGenerator<ProviderEvent> {
      this.calls += 1;
      providerStarted?.();
      if (options.signal?.aborted) throw new GeorgeError('cancelled', 'Stopped');
      await new Promise<never>((_resolve, reject) => options.signal?.addEventListener(
        'abort',
        () => reject(new GeorgeError('cancelled', 'Stopped')),
        { once: true },
      ));
    }
  }();
  const cancelledService = await createOneTurnApplicationService({ provider: cancelled, workspace: root });
  const controller = new AbortController();
  const cancelledRun = collect(cancelledService.run({
    session: createSession({ workspace: root }), input: 'Stop', turnId: 'turn-3', signal: controller.signal,
  }));
  await started;
  controller.abort();
  const cancelledEvents = await cancelledRun;
  assert.equal(cancelled.calls, 1);
  assert.equal(cancelledEvents.at(-1)?.type, 'turn.cancelled');

  const failed = new ScriptedProvider([], new Error('offline'));
  const failedService = await createOneTurnApplicationService({ provider: failed, workspace: root });
  const failedEvents = await collect(failedService.run({ session: createSession({ workspace: root }), input: 'Fail', turnId: 'turn-4' }));
  assert.equal(failed.calls.length, 1);
  assert.equal(failedEvents.at(-1)?.type, 'turn.failed');
});
